import{_ as e,a as o}from"./chunks/scalar_atomic_operation_diagram.CJEsyM48.js";import{_ as a,o as d,a as i,b as c}from"./app.DKoEZOcr.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"原子操作","link":"/api/SIMD-API/basic_api/atomic_operations/atomic_operations"},{"text":"原子操作概述","link":"/api/SIMD-API/basic_api/atomic_operations/atomic_operations_overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/atomic_operations/atomic_operations_overview.md","filePath":"api/SIMD-API/basic_api/atomic_operations/atomic_operations_overview.md","lastUpdated":1788779714000}'),r={name:"api/SIMD-API/basic_api/atomic_operations/atomic_operations_overview.md"};function l(s,t,_,m,p,n){return d(),i("div",null,[...t[0]||(t[0]=[c('<div><article class="markdown-body"><h1>原子操作概述<span id="ZH-CN_TOPIC_0000002555621180"></span></h1><p>数据搬运随路原子操作接口用于对后续目的地址为GM的数据搬运开启原子操作，涉及的接口请参见<a href="#table1">表1</a>。如下图1的左侧子图所示，未开启原子操作时，写入GM的数据搬运完成后，GM中原始数据将被新搬运数据完全覆盖。如图1右侧子图所示，当数据搬运随路原子操作接口被调用后，系统将为后续写入GM的数据搬运开启原子操作。此时，数据搬运完成后，GM中的最终数据由原始GM数据与新搬运数据共同决定。</p><p><strong>图1</strong> 数据搬运随路原子累加效果<br><img src="'+e+'" alt title="数据搬运随路原子累加效果"></p><p><strong>表1</strong> 数据搬运随路原子操作接口<span id="table1"></span></p><table><thead><tr><th>对应接口</th><th>接口功能描述</th></tr></thead><tbody><tr><td><a href="SetAtomicAdd.html">SetAtomicAdd</a></td><td>对后续目的地址为GM的数据搬运开启原子累加。原子累加过程：将待拷贝的内容和GM已有内容进行求和，然后将求和结果写入GM。</td></tr><tr><td><a href="SetAtomicType.html">SetAtomicType</a></td><td>通过设置模板参数来设定原子操作不同的数据类型。</td></tr><tr><td><a href="DisableDmaAtomic.html">DisableDmaAtomic</a></td><td>关闭数据搬运随路原子操作功能。</td></tr><tr><td><a href="SetAtomicMax_ISASI.html">SetAtomicMax(ISASI)</a></td><td>设置后续搬运到GM的数据是否执行原子比较：将待拷贝的内容和GM已有内容进行比较，然后将最大值写入GM。</td></tr><tr><td><a href="SetAtomicMin_ISASI.html">SetAtomicMin(ISASI)</a></td><td>设置后续搬运到GM的数据是否执行原子比较：将待拷贝的内容和GM已有内容进行比较，然后将最小值写入GM。</td></tr><tr><td><a href="SetStoreAtomicConfig_ISASI.html">SetStoreAtomicConfig(ISASI)</a></td><td>设置数据搬运的原子操作配置。</td></tr><tr><td><a href="GetStoreAtomicConfig_ISASI.html">GetStoreAtomicConfig(ISASI)</a></td><td>获取数据搬运的原子操作配置。</td></tr></tbody></table><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT新增Scalar原子操作接口，能够在指定GM地址上进行单点原子计算操作，涉及的接口请参见<a href="#table2">表2</a>。对比数据搬运随路原子操作接口，Scalar原子操作接口不会影响后续向GM搬运数据的指令。</p><p>如下图2左侧子图所示，不使用AtomicAdd接口时，多个AI Core同时对同一GM地址执行累加操作会相互覆盖，操作不具备原子性，最终结果不可预期。如右侧子图所示，使用AtomicAdd接口后，各AI Core的累加操作串行化执行，确保每次累加操作的原子性，最终结果符合预期。</p><p><strong>图2</strong> 标量原子累加效果<br><img src="'+o+'" alt title="标量原子累加效果"></p><p><strong>表2</strong> Scalar原子操作接口<span id="table2"></span></p><table><thead><tr><th>对应接口</th><th>接口功能描述</th></tr></thead><tbody><tr><td><a href="AtomicAdd.html">AtomicAdd</a></td><td>用于在指定GM地址上进行原子加操作，将<code>address</code>指向的GM地址上的旧值（<code>old_value</code>）与输入标量值（<code>value</code>）求和，将和结果（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="AtomicMin.html">AtomicMin</a></td><td>用于在指定GM地址上进行原子取最小值操作，将<code>address</code>指向的GM地址上的旧值（<code>old_value</code>）与输入标量值（<code>value</code>）做比较，将较小值（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="AtomicMax.html">AtomicMax</a></td><td>该接口用于在指定GM地址上进行原子取最大值操作，将<code>address</code>指向的GM地址上的旧值（<code>old_value</code>）与输入的标量值（<code>value</code>）进行比较，将较大值（<code>new_value</code>）写回GM地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="AtomicCas.html">AtomicCas</a></td><td>在指定GM地址上进行原子比较操作，读取<code>address</code>指向的GM地址上的旧值（<code>old_value</code>）与输入标量值<code>value1</code>进行比较：如果相等，则将输入标量值<code>value2</code>写入GM地址；如果不相等，则GM地址上的值保持不变。返回该地址修改前的值（<code>old_value</code>）。</td></tr><tr><td><a href="AtomicExch.html">AtomicExch</a></td><td>用于在GM内存中执行原子交换操作，读取<code>address</code>指向的GM地址上的旧值（<code>old_value</code>），并将输入的标量值（<code>value</code>）替换旧值存储回同一地址，返回该地址修改前的值（<code>old_value</code>）。</td></tr></tbody></table></div></article></div>',1)])])}const h=a(r,[["render",l]]);export{S as __pageData,h as default};
